def device_notes_for(conn, caller_id, device_id):
    if not may_view_device(conn, caller_id, device_id):
        return None
    return conn.execute(
        "SELECT * FROM device_notes WHERE device_id = ? AND author_account_id = ? ORDER BY id",
        (device_id, caller_id),
    ).fetchall()

def update_device(device_id: int, body: DeviceUpdate, request: Request):
    account = current(request)
    label = body.label.strip()
    if not label:
        fail(400, "invalid device")
    row = request.app.state.conn.execute("SELECT * FROM devices WHERE id = ?", (device_id,)).fetchone()
    if row is None:
        fail(404, "not found")
    if int(row["owner_account_id"]) != int(account["id"]):
        fail(403, "forbidden")
    request.app.state.conn.execute("UPDATE devices SET label = ? WHERE id = ?", (label, device_id))
    request.app.state.conn.commit()

def account_for_token(conn, token):
    row = conn.execute("SELECT account_id FROM sessions WHERE token = ?", (token,)).fetchone()
    if row is None:
        return None
    account = conn.execute("SELECT * FROM accounts WHERE id = ?", (row["account_id"],)).fetchone()
    if account is None:
        return None
    if account["status"] != "active" or account["merged_into_id"] is not None:
        return None
    return account

